USE LGCE_SCMDEV
GO
BEGIN
EXEC PR_SCM_SYS_RFC_CALL_NERP 'ZCMCM_AS_TOBE_CODE_INFO';
EXEC PR_NERP_XLS_TOBE_CONVERTER @p_rollin='5TH',@p_sys_type='ALL';
END;

1차 기준 SELECT * FROM NERP_CONV_SCP_RUN_DT_RANGE WITH(NOLOCK) WHERE MODULE='SCP' AND ROLLIN='1ST' ORDER BY RTYPE_NUM DESC
/* 시작일자는 포함이고 종료일자는 끝자리보다 작은 날자임*/
전제 컨버전 대상 모두가 대상임

1차 기준 SELECT * FROM NERP_CONV_SCP_RUN_DT_RANGE WITH(NOLOCK) WHERE ROLLIN='1ST' ORDER BY RTYPE_NUM DESC
/* 시작일자는 포함이고 종료일자는 끝자리보다 작은 날자임*/
전제 컨버전 대상 모두가 대상임, 검증프로그램만 실행함, 실제 데이터는 컨버전 하지 않음.

2차 기준 SELECT * FROM NERP_CONV_SCP_RUN_DT_RANGE WITH(NOLOCK) WHERE MODULE='SCP' AND ROLLIN='2ND' ORDER BY RTYPE_NUM DESC
/* 시작일자는 포함이고 종료일자는 끝자리보다 작은 날자임*/
전제 컨버전 대상 모두가 대상임
